#!/usr/bin/env python3
"""Generate template/tiko.sublime-syntax from tiko's own keyword table.

The book's highlighting can never disagree with the compiler about what a keyword is,
because the word lists come from src/lexer/keywords.bi, which the compiler itself uses.

    python tools/gen_syntax.py [--tiko-src C:/dev/tiko-lang] [--check]

--check exits 1 if the generated file would differ from the one on disk. The PDF build
runs it that way, so a stale syntax file fails the build instead of quietly mis-colouring
a listing.
"""
from __future__ import annotations

import argparse
import pathlib
import re
import sys

import pin as pinlib

# Not reserved words: the lexer keeps treating them as identifiers, so they are only
# highlighted where tiko itself gives them meaning. See keywords.bi's header comment and
# src/parser/{parser,selchan,spawn}.bas.
CONTEXTUAL = [
    "defer", "each", "in", "of", "spawn",
    "channel", "receive", "send", "timeout", "from",
    "override", "naked",
]

KW_RE = re.compile(r'KW\(\s*KW_[A-Z0-9_]+,\s*"([A-Z0-9_]+)",\s*KWCLASS_([A-Z]+)\s*\)')

SCOPE = {
    "OPERATOR": "keyword.operator.word.tiko",
    "KEYWORD": "keyword.control.tiko",
    "INTRINSIC": "support.function.intrinsic.tiko",
}


def read_keywords(pin: "pinlib.Pin") -> dict[str, list[str]]:
    text = pinlib.read_source(pin, "src/lexer/keywords.bi")
    out: dict[str, list[str]] = {"OPERATOR": [], "KEYWORD": [], "INTRINSIC": []}
    for spelling, cls in KW_RE.findall(text):
        out[cls].append(spelling.lower())
    if not all(out.values()):
        sys.exit(f"gen_syntax: keywords.bi parsed to an empty class at {pin.commit} "
                 f"-- the table's shape changed")
    return out


def alternation(words: list[str]) -> str:
    # Longest first, so `endif` is not matched as `end` + `if`.
    return "|".join(sorted(set(words), key=lambda w: (-len(w), w)))


def build(words: dict[str, list[str]]) -> str:
    total = sum(len(v) for v in words.values())
    lines = [
        "%YAML 1.2",
        "---",
        "# GENERATED by tools/gen_syntax.py from tiko's src/lexer/keywords.bi. Do not edit.",
        f"# {total} reserved words ("
        + ", ".join(f"{len(words[c])} {c.lower()}" for c in ("OPERATOR", "KEYWORD", "INTRINSIC"))
        + f") plus {len(CONTEXTUAL)} contextual words.",
        "name: tiko",
        "file_extensions: [tiko, ti, bas, bi, inc]",
        "scope: source.tiko",
        "contexts:",
        "  main:",
        "    - include: comments",
        "    - include: strings",
        "    - include: numbers",
        "    - include: directives",
        "    - include: words",
        "",
        "  comments:",
        "    - match: \"'.*$\"",
        "      scope: comment.line.apostrophe.tiko",
        "    - match: \\b(?i:rem)\\b.*$",
        "      scope: comment.line.rem.tiko",
        "    - match: /'",
        "      push:",
        "        - meta_scope: comment.block.tiko",
        "        - match: \"'/\"",
        "          pop: true",
        "        - match: /'",       # tiko nests block comments
        "          push:",
        "            - meta_scope: comment.block.tiko",
        "            - match: \"'/\"",
        "              pop: true",
        "",
        "  strings:",
        "    - match: '(?i:[!$])?\"'",
        "      push:",
        "        - meta_scope: string.quoted.double.tiko",
        "        - match: '\\\\.'",
        "          scope: constant.character.escape.tiko",
        "        - match: '\"\"'",
        "          scope: constant.character.escape.tiko",
        "        - match: '\"'",
        "          pop: true",
        "        - match: $",
        "          pop: true",
        "",
        "  numbers:",
        "    - match: '&[hH][0-9a-fA-F]+(?i:u|l|ll|ul|ull)?'",
        "      scope: constant.numeric.hex.tiko",
        "    - match: '&[oO][0-7]+'",
        "      scope: constant.numeric.octal.tiko",
        "    - match: '&[bB][01]+'",
        "      scope: constant.numeric.binary.tiko",
        "    - match: '\\b\\d+(\\.\\d*)?([eEdD][-+]?\\d+)?(?i:f|d|u|l|ll|ul|ull)?\\b'",
        "      scope: constant.numeric.tiko",
        "",
        "  directives:",
        "    - match: '^\\s*#\\s*[A-Za-z_]+'",
        "      scope: keyword.control.directive.tiko",
        "    - match: '\\b__[A-Z_]+__\\b'",
        "      scope: constant.language.predefined.tiko",
        "",
        "  words:",
    ]
    for cls in ("OPERATOR", "KEYWORD", "INTRINSIC"):
        lines += [
            f"    - match: \\b(?i:{alternation(words[cls])})\\b",
            f"      scope: {SCOPE[cls]}",
        ]
    lines += [
        f"    - match: \\b(?i:{alternation(CONTEXTUAL)})\\b",
        "      scope: keyword.other.contextual.tiko",
        "    - match: '\\b(?i:true|false)\\b'",
        "      scope: constant.language.tiko",
        "",
    ]
    return "\n".join(lines)


def build_highlight_js(words: dict[str, list[str]], template: pathlib.Path) -> str:
    """Fill the highlight.js template with the compiler's word lists.

    The JavaScript lives in tools/templates/tiko-highlight.js.in as real JavaScript, and
    only the word lists are substituted. Building the file from a string inside this
    generator kept losing a backslash -- `illegal: "\n"` shipped as a literal newline and
    the whole script died with "Invalid or unexpected token", silently leaving every
    listing unstyled.
    """
    js = template.read_text(encoding="utf-8")
    kw = " ".join(sorted(set(words["KEYWORD"] + words["OPERATOR"] + CONTEXTUAL)))
    built_in = " ".join(sorted(set(words["INTRINSIC"])))
    js = js.replace("@KEYWORDS@", kw).replace("@BUILTINS@", built_in)
    if "@" in js.split("// GENERATED", 1)[-1].split("(function", 1)[0]:
        pass
    for left in ("@KEYWORDS@", "@BUILTINS@"):
        assert left not in js, f"gen_syntax: {left} was not substituted"
    return js


def main() -> int:
    here = pathlib.Path(__file__).resolve().parent.parent
    ap = argparse.ArgumentParser()
    pinlib.add_arguments(ap)
    ap.add_argument("--out", default=str(here / "template" / "tiko.sublime-syntax"))
    ap.add_argument("--highlight-out", default=str(here / "src" / "theme" / "tiko-highlight.js"))
    ap.add_argument("--highlight-template", default=str(here / "tools" / "templates" / "tiko-highlight.js.in"))
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()

    pin = pinlib.read_pin(args.tiko_src, args.rev, args.worktree)
    if not args.check:
        pinlib.announce(pin, "gen_syntax")
    words = read_keywords(pin)
    text = build(words)
    out = pathlib.Path(args.out)
    if args.check:
        if not out.exists() or out.read_text(encoding="utf-8") != text:
            print(f"gen_syntax: {out} is out of date -- run tools/gen_syntax.py", file=sys.stderr)
            return 1
        return 0
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(text, encoding="utf-8", newline="\n")
    print(f"gen_syntax: wrote {out}")

    js = pathlib.Path(args.highlight_out)
    js.parent.mkdir(parents=True, exist_ok=True)
    js.write_text(
        build_highlight_js(words, pathlib.Path(args.highlight_template)),
        encoding="utf-8",
        newline="\n",
    )
    print(f"gen_syntax: wrote {js}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
